import{_ as e,o as i,c as t,a3 as s}from"./chunks/framework.B5WAEDB7.js";const r="/assets/images/Q6z24La.png",n="/assets/images/ONjORqk.png",h="/assets/images/0vBc0hN.png",l="/assets/images/rgSrvjG.png",c="/assets/images/kxtjqgE.png",m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"core-concepts/cache.md","filePath":"core-concepts/cache.md"}'),o={name:"core-concepts/cache.md"};function d(p,a,u,g,k,y){return i(),t("div",null,[...a[0]||(a[0]=[s('<h2 id="cache" tabindex="-1">Cache <a class="header-anchor" href="#cache" aria-label="Permalink to &quot;Cache&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Key Takeaways</p><ul><li>Understand the core principles of Cache.</li><li>Focus on the trade-offs involved in different approaches.</li><li>Keep scalability and performance in mind.</li></ul></div><p align="center"><img src="'+r+'"><br><i><a href="http://horicky.blogspot.com/2010/10/scalable-system-design-patterns.html">Source: Scalable system design patterns</a></i></p><p>Caching improves page load times and can reduce the load on your servers and databases. In this model, the dispatcher will first lookup if the request has been made before and try to find the previous result to return, in order to save the actual execution.</p><p>Databases often benefit from a uniform distribution of reads and writes across its partitions. Popular items can skew the distribution, causing bottlenecks. Putting a cache in front of a database can help absorb uneven loads and spikes in traffic.</p><h3 id="client-caching" tabindex="-1">Client caching <a class="header-anchor" href="#client-caching" aria-label="Permalink to &quot;Client caching&quot;">​</a></h3><p>Caches can be located on the client side (OS or browser), <a href="/core-concepts/reverse-proxy.html">server side</a>, or in a distinct cache layer.</p><h3 id="cdn-caching" tabindex="-1">CDN caching <a class="header-anchor" href="#cdn-caching" aria-label="Permalink to &quot;CDN caching&quot;">​</a></h3><p><a href="/core-concepts/content-delivery-network.html">CDNs</a> are considered a type of cache.</p><h3 id="web-server-caching" tabindex="-1">Web server caching <a class="header-anchor" href="#web-server-caching" aria-label="Permalink to &quot;Web server caching&quot;">​</a></h3><p><a href="/core-concepts/reverse-proxy.html">Reverse proxies</a> and caches such as <a href="https://www.varnish-cache.org/" target="_blank" rel="noreferrer">Varnish</a> can serve static and dynamic content directly. Web servers can also cache requests, returning responses without having to contact application servers.</p><h3 id="database-caching" tabindex="-1">Database caching <a class="header-anchor" href="#database-caching" aria-label="Permalink to &quot;Database caching&quot;">​</a></h3><p>Your database usually includes some level of caching in a default configuration, optimized for a generic use case. Tweaking these settings for specific usage patterns can further boost performance.</p><h3 id="application-caching" tabindex="-1">Application caching <a class="header-anchor" href="#application-caching" aria-label="Permalink to &quot;Application caching&quot;">​</a></h3><p>In-memory caches such as Memcached and Redis are key-value stores between your application and your data storage. Since the data is held in RAM, it is much faster than typical databases where data is stored on disk. RAM is more limited than disk, so <a href="https://en.wikipedia.org/wiki/Cache_algorithms" target="_blank" rel="noreferrer">cache invalidation</a> algorithms such as <a href="https://en.wikipedia.org/wiki/Cache_replacement_policies#Least_recently_used_(LRU)" target="_blank" rel="noreferrer">least recently used (LRU)</a> can help invalidate &#39;cold&#39; entries and keep &#39;hot&#39; data in RAM.</p><p>Redis has the following additional features:</p><ul><li>Persistence option</li><li>Built-in data structures such as sorted sets and lists</li></ul><p>There are multiple levels you can cache that fall into two general categories: <strong>database queries</strong> and <strong>objects</strong>:</p><ul><li>Row level</li><li>Query-level</li><li>Fully-formed serializable objects</li><li>Fully-rendered HTML</li></ul><p>Generally, you should try to avoid file-based caching, as it makes cloning and auto-scaling more difficult.</p><h3 id="caching-at-the-database-query-level" tabindex="-1">Caching at the database query level <a class="header-anchor" href="#caching-at-the-database-query-level" aria-label="Permalink to &quot;Caching at the database query level&quot;">​</a></h3><p>Whenever you query the database, hash the query as a key and store the result to the cache. This approach suffers from expiration issues:</p><ul><li>Hard to delete a cached result with complex queries</li><li>If one piece of data changes such as a table cell, you need to delete all cached queries that might include the changed cell</li></ul><h3 id="caching-at-the-object-level" tabindex="-1">Caching at the object level <a class="header-anchor" href="#caching-at-the-object-level" aria-label="Permalink to &quot;Caching at the object level&quot;">​</a></h3><p>See your data as an object, similar to what you do with your application code. Have your application assemble the dataset from the database into a class instance or a data structure(s):</p><ul><li>Remove the object from cache if its underlying data has changed</li><li>Allows for asynchronous processing: workers assemble objects by consuming the latest cached object</li></ul><p>Suggestions of what to cache:</p><ul><li>User sessions</li><li>Fully rendered web pages</li><li>Activity streams</li><li>User graph data</li></ul><h3 id="when-to-update-the-cache" tabindex="-1">When to update the cache <a class="header-anchor" href="#when-to-update-the-cache" aria-label="Permalink to &quot;When to update the cache&quot;">​</a></h3><p>Since you can only store a limited amount of data in cache, you&#39;ll need to determine which cache update strategy works best for your use case.</p><h4 id="cache-aside" tabindex="-1">Cache-aside <a class="header-anchor" href="#cache-aside" aria-label="Permalink to &quot;Cache-aside&quot;">​</a></h4><p align="center"><img src="'+n+`"><br><i><a href="http://www.slideshare.net/tmatyashovsky/from-cache-to-in-memory-data-grid-introduction-to-hazelcast">Source: From cache to in-memory data grid</a></i></p><p>The application is responsible for reading and writing from storage. The cache does not interact with storage directly. The application does the following:</p><ul><li>Look for entry in cache, resulting in a cache miss</li><li>Load entry from the database</li><li>Add entry to cache</li><li>Return entry</li></ul><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> get_user</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(self, user_id):</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    user </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> cache.get(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;user.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{0}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, user_id)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> user </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">is</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> None</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        user </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> db.query(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;SELECT * FROM users WHERE user_id = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{0}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, user_id)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> user </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">is</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> not</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> None</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            key </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;user.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{0}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.format(user_id)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            cache.set(key, json.dumps(user))</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> user</span></span></code></pre></div><p><a href="https://memcached.org/" target="_blank" rel="noreferrer">Memcached</a> is generally used in this manner.</p><p>Subsequent reads of data added to cache are fast. Cache-aside is also referred to as lazy loading. Only requested data is cached, which avoids filling up the cache with data that isn&#39;t requested.</p><h5 id="disadvantage-s-cache-aside" tabindex="-1">Disadvantage(s): cache-aside <a class="header-anchor" href="#disadvantage-s-cache-aside" aria-label="Permalink to &quot;Disadvantage(s): cache-aside&quot;">​</a></h5><ul><li>Each cache miss results in three trips, which can cause a noticeable delay.</li><li>Data can become stale if it is updated in the database. This issue is mitigated by setting a time-to-live (TTL) which forces an update of the cache entry, or by using write-through.</li><li>When a node fails, it is replaced by a new, empty node, increasing latency.</li></ul><h4 id="write-through" tabindex="-1">Write-through <a class="header-anchor" href="#write-through" aria-label="Permalink to &quot;Write-through&quot;">​</a></h4><p align="center"><img src="`+h+`"><br><i><a href="http://www.slideshare.net/jboner/scalability-availability-stability-patterns/">Source: Scalability, availability, stability, patterns</a></i></p><p>The application uses the cache as the main data store, reading and writing data to it, while the cache is responsible for reading and writing to the database:</p><ul><li>Application adds/updates entry in cache</li><li>Cache synchronously writes entry to data store</li><li>Return</li></ul><p>Application code:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">set_user(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">12345</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, {</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;foo&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;bar&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span></code></pre></div><p>Cache code:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> set_user</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(user_id, values):</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    user </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> db.query(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;UPDATE Users WHERE id = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{0}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, user_id, values)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    cache.set(user_id, user)</span></span></code></pre></div><p>Write-through is a slow overall operation due to the write operation, but subsequent reads of just written data are fast. Users are generally more tolerant of latency when updating data than reading data. Data in the cache is not stale.</p><h5 id="disadvantage-s-write-through" tabindex="-1">Disadvantage(s): write through <a class="header-anchor" href="#disadvantage-s-write-through" aria-label="Permalink to &quot;Disadvantage(s): write through&quot;">​</a></h5><ul><li>When a new node is created due to failure or scaling, the new node will not cache entries until the entry is updated in the database. Cache-aside in conjunction with write through can mitigate this issue.</li><li>Most data written might never be read, which can be minimized with a TTL.</li></ul><h4 id="write-behind-write-back" tabindex="-1">Write-behind (write-back) <a class="header-anchor" href="#write-behind-write-back" aria-label="Permalink to &quot;Write-behind (write-back)&quot;">​</a></h4><p align="center"><img src="`+l+'"><br><i><a href="http://www.slideshare.net/jboner/scalability-availability-stability-patterns/">Source: Scalability, availability, stability, patterns</a></i></p><p>In write-behind, the application does the following:</p><ul><li>Add/update entry in cache</li><li>Asynchronously write entry to the data store, improving write performance</li></ul><h5 id="disadvantage-s-write-behind" tabindex="-1">Disadvantage(s): write-behind <a class="header-anchor" href="#disadvantage-s-write-behind" aria-label="Permalink to &quot;Disadvantage(s): write-behind&quot;">​</a></h5><ul><li>There could be data loss if the cache goes down prior to its contents hitting the data store.</li><li>It is more complex to implement write-behind than it is to implement cache-aside or write-through.</li></ul><h4 id="refresh-ahead" tabindex="-1">Refresh-ahead <a class="header-anchor" href="#refresh-ahead" aria-label="Permalink to &quot;Refresh-ahead&quot;">​</a></h4><p align="center"><img src="'+c+'"><br><i><a href="http://www.slideshare.net/tmatyashovsky/from-cache-to-in-memory-data-grid-introduction-to-hazelcast">Source: From cache to in-memory data grid</a></i></p><p>You can configure the cache to automatically refresh any recently accessed cache entry prior to its expiration.</p><p>Refresh-ahead can result in reduced latency vs read-through if the cache can accurately predict which items are likely to be needed in the future.</p><h5 id="disadvantage-s-refresh-ahead" tabindex="-1">Disadvantage(s): refresh-ahead <a class="header-anchor" href="#disadvantage-s-refresh-ahead" aria-label="Permalink to &quot;Disadvantage(s): refresh-ahead&quot;">​</a></h5><ul><li>Not accurately predicting which items are likely to be needed in the future can result in reduced performance than without refresh-ahead.</li></ul><h3 id="disadvantage-s-cache" tabindex="-1">Disadvantage(s): cache <a class="header-anchor" href="#disadvantage-s-cache" aria-label="Permalink to &quot;Disadvantage(s): cache&quot;">​</a></h3><ul><li>Need to maintain consistency between caches and the source of truth such as the database through <a href="https://en.wikipedia.org/wiki/Cache_algorithms" target="_blank" rel="noreferrer">cache invalidation</a>.</li><li>Cache invalidation is a difficult problem, there is additional complexity associated with when to update the cache.</li><li>Need to make application changes such as adding Redis or memcached.</li></ul><h3 id="source-s-and-further-reading" tabindex="-1">Source(s) and further reading <a class="header-anchor" href="#source-s-and-further-reading" aria-label="Permalink to &quot;Source(s) and further reading&quot;">​</a></h3><ul><li><a href="http://www.slideshare.net/tmatyashovsky/from-cache-to-in-memory-data-grid-introduction-to-hazelcast" target="_blank" rel="noreferrer">From cache to in-memory data grid</a></li><li><a href="http://horicky.blogspot.com/2010/10/scalable-system-design-patterns.html" target="_blank" rel="noreferrer">Scalable system design patterns</a></li><li><a href="http://lethain.com/introduction-to-architecting-systems-for-scale/" target="_blank" rel="noreferrer">Introduction to architecting systems for scale</a></li><li><a href="http://www.slideshare.net/jboner/scalability-availability-stability-patterns/" target="_blank" rel="noreferrer">Scalability, availability, stability, patterns</a></li><li><a href="https://web.archive.org/web/20230126233752/https://www.lecloud.net/post/9246290032/scalability-for-dummies-part-3-cache" target="_blank" rel="noreferrer">Scalability</a></li><li><a href="http://docs.aws.amazon.com/AmazonElastiCache/latest/UserGuide/Strategies.html" target="_blank" rel="noreferrer">AWS ElastiCache strategies</a></li><li><a href="https://en.wikipedia.org/wiki/Cache_(computing)" target="_blank" rel="noreferrer">Wikipedia</a></li></ul>',66)])])}const f=e(o,[["render",d]]);export{m as __pageData,f as default};
